pub fn scan_library(
    library_paths: &[String],
    filters: &crate::config::FilterConfig,
    cancel: Option<&std::sync::atomic::AtomicBool>,
    progress: Option<&dyn ScanProgress>,
) -> Result<Vec<ScannedAlbum>> {
