=== discs::album_index ===
//! Disc-designator parsing shared by the download stager (`download.rs`) and
//! the library organizer (`organizer.rs`). Both must agree on what counts as
//! a per-disc folder so multi-disc albums are staged and copied with the
//! same structure — otherwise identical basenames across discs ("01 -
//! Track.flac" on both CD 01 and CD 02) can collide in one flat directory.

use regex::Regex;
use std::sync::OnceLock;

/// True when a directory leaf is a dedicated disc designator, e.g. "CD 01",
/// "CD1", "Disc 2", "disc 02" (case-insensitive), including a designator
/// wrapped in brackets, braces, or parentheses such as "{cd1}".
pub fn is_disc_folder(leaf: &str) -> bool {
    let trimmed = leaf.trim();
    let trimmed = match (trimmed.as_bytes().first(), trimmed.as_bytes().last()) {
        (Some(b'{'), Some(b'}')) | (Some(b'['), Some(b']')) | (Some(b'('), Some(b')')) => {
            trimmed[1..trimmed.len() - 1].trim()
        }
        _ => trimmed,
    };
    parse_disc_label(trimmed).is_some()
}

fn parse_disc_label(label: &str) -> Option<u32> {
    let lower = label.trim().to_ascii_lowercase();
    let rest = lower
        .strip_prefix("disc")
        .or_else(|| lower.strip_prefix("disk"))
        .or_else(|| lower.strip_prefix("cd"))?
        .trim_start();
    let digit_count = rest
        .chars()
        .take_while(|character| character.is_ascii_digit())
        .count();
    let disc: u32 = rest[..digit_count].parse().ok()?;
    let remainder = rest[digit_count..].trim();
    if remainder.is_empty()
        || remainder
            .strip_prefix("of")
            .or_else(|| remainder.strip_prefix('/'))
            .is_some_and(|total| {
                total
                    .trim()
                    .chars()
                    .all(|character| character.is_ascii_digit())
            })
    {
        Some(disc)
    } else {
        None
    }
}

/// Index of the album component in a slash-split path, peeling one dedicated
/// disc folder.
///
/// The album component is the one holding the files. A dedicated disc folder
/// ("CD 01", "Disc 2") is stepped over, so the album is the folder above it.
/// Embedded markers ("Gold (Disc 1)") are not peeled here — the album
/// component is the folder holding the files, and each caller decides what to
/// do with a marker: the peer-side parser folds it with
/// [`strip_embedded_disc_marker`], while the library scanner keeps the on-disk
/// folder name verbatim because it is the identity the upgrade copy and the
/// quality-deletion root use.
///
/// Returns `None` when no artist component would remain above the album, which
/// leaves the caller to decide whether that shape is an album folder (a library
/// folder named like a disc) or unusable (a peer share path).
pub fn album_index(components: &[&str]) -> Option<usize> {
    let index = components.len().checked_sub(2)?;
    let index = if is_disc_folder(components[index]) {
        index.checked_sub(1)?
    } else {
        index
    };
    (index > 0).then_some(index)
}

