//! Read-only reproduction of the reported discover-mode failure.
//!
//! Two modes:
//!   cargo run --              -> synthetic fixtures under /tmp (shapes A-D)
//!   cargo run -- <library>    -> the same scan/index/select path on a real
//!                                library subtree, read-only, nothing written.

use std::collections::BTreeSet;
use std::fs;
use std::path::{Path, PathBuf};

use seakarr::config::{Config, FilterConfig};
use seakarr::discover::{self, ArtistFolderIndex};

fn touch(path: &Path) {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).unwrap();
    }
    fs::write(path, b"not really audio").unwrap();
}

/// Drive the exact pipeline `run_discover_mode_with_provider` uses before it
/// builds the work list: scan -> build_index -> select_artists.
fn pipeline(label: &str, root: &Path, artist_filter: Option<&str>) {
    let paths = vec![root.to_string_lossy().to_string()];
    let albums =
        seakarr::scanner::scan_library(&paths, &FilterConfig::default(), None, None).unwrap();
    let index = discover::build_index(&albums);
    let keys: Vec<&str> = index.artist_keys().collect();

    println!("\n### {label}");
    println!("  root                = {}", root.display());
    println!("  scanned albums      = {}", albums.len());
    println!("  LibraryIndex artists= {}", keys.len());

    for needle in ["shy fx", "Shy Fx", "shy fx "] {
        println!(
            "  has_artist({needle:?}) = {}  owns_folder = {}",
            index.has_artist(needle),
            index.owns_folder(&seakarr::discography::normalize_catalog_key(needle))
        );
    }

    match discover::select_artists(&index, &[], artist_filter) {
        Ok(sel) => println!(
            "  select_artists(filter {:?}) = Ok(artists {:?}, no_folder {:?})",
            artist_filter,
            sel.artists.iter().map(|a| a.name.clone()).collect::<Vec<_>>(),
            sel.no_folder
        ),
        Err(e) => println!("  select_artists(filter {artist_filter:?}) = Err({e})"),
    }

    let mut config = Config::default();
    config.library.paths = paths.clone();
    let folder_index = ArtistFolderIndex::new(&config);
    println!(
        "  ArtistFolderIndex::find(\"shy fx\") = {:?}",
        folder_index.find("shy fx")
    );

    // Directories on disk vs directories that produced at least one album.
    let mut dirs: BTreeSet<String> = BTreeSet::new();
    if let Ok(entries) = fs::read_dir(root) {
        for entry in entries.flatten() {
            if entry.file_type().map(|t| t.is_dir()).unwrap_or(false) {
                dirs.insert(entry.file_name().to_string_lossy().to_string());
            }
        }
    }
    let scanned_dirs: BTreeSet<String> = albums
        .iter()
        .flat_map(|a| a.artist_dirs.iter().cloned())
        .collect();
    println!("  direct child folders on disk = {}", dirs.len());
    println!(
        "  folders that produced an album = {}",
        scanned_dirs.len()
    );
    let silent: Vec<&String> = dirs.difference(&scanned_dirs).collect();
    println!("  folders with NO album scanned ({}) = {silent:?}", silent.len());
}

fn fixtures() {
    let base = PathBuf::from("/tmp/seakarr-repro-lib");
    let _ = fs::remove_dir_all(&base);

    // A) Root = the genre directory, exactly as passed on the CLI. Reported
    //    shape: the artist folder exists but is empty.
    let a = base.join("A/Drum And Bass");
    touch(&a.join("Good Artist/Good Album/01 - hit.flac"));
    fs::create_dir_all(a.join("Shy Fx")).unwrap();
    pipeline("A) root=genre dir; artist folder EMPTY", &a, Some("shy fx"));

    // B) Root = the genre directory; the artist folder holds a loose track but
    //    no album subfolder.
    let b = base.join("B/Drum And Bass");
    touch(&b.join("Good Artist/Good Album/01 - hit.flac"));
    touch(&b.join("Shy Fx/01 - loose track.flac"));
    pipeline("B) root=genre dir; artist folder holds a LOOSE track", &b, Some("shy fx"));

    // C) Same as B but the root is one level higher (nested library shape).
    let c = base.join("C");
    touch(&c.join("Drum And Bass/Good Artist/Good Album/01 - hit.flac"));
    touch(&c.join("Drum And Bass/Shy Fx/01 - loose track.flac"));
    pipeline("C) root=parent of genre dir; artist folder holds a LOOSE track", &c, Some("shy fx"));

    // D) Root = the genre directory; the artist folder holds only artwork.
    let d = base.join("D/Drum And Bass");
    touch(&d.join("Good Artist/Good Album/01 - hit.flac"));
    touch(&d.join("Shy Fx/Some Album/folder.jpg"));
    pipeline("D) root=genre dir; artist folder holds only ARTWORK", &d, Some("shy fx"));
}

fn main() {
    match std::env::args().nth(1) {
        Some(path) => pipeline("REAL LIBRARY (read-only)", Path::new(&path), Some("shy fx")),
        None => fixtures(),
    }
}

