//! Read-only verification of the discover-mode fix against a real library.
//!
//! Drives the exact pipeline `run_discover_mode_with_provider` uses:
//!   scan -> build_index -> (folder lookup when the name is absent) -> select_artists
//!
//! Nothing is written; the library is only read.

use std::path::Path;

use seakarr::config::{Config, FilterConfig};
use seakarr::discover::{self, ArtistDestination, ArtistFolderIndex};

fn report(root: &str, artist_filter: &str) {
    let mut config = Config::default();
    config.library.paths = vec![root.to_string()];
    config.discover.exclude_artists = Vec::new();

    let albums =
        seakarr::scanner::scan_library(&config.library.paths, &FilterConfig::default(), None, None)
            .unwrap();
    let index = discover::build_index(&albums);

    // The runner's wiring: resolve folder evidence only for a name the
    // album-derived index does not already hold.
    let folder = if index.has_artist(artist_filter) {
        None
    } else {
        ArtistFolderIndex::new(&config).find(artist_filter)
    };

    println!("\n=== --artist {artist_filter:?} on {root}");
    println!("  scanned albums = {}", albums.len());
    println!("  index has the artist = {}", index.has_artist(artist_filter));
    println!("  folder resolved to   = {folder:?}");

    let selection = discover::select_artists(
        &index,
        &config.discover.exclude_artists,
        Some(artist_filter),
        folder
            .as_ref()
            .map(|(parent, name)| (parent.as_path(), name.as_str())),
    );

    match selection {
        Ok(selection) => {
            for artist in &selection.artists {
                match &artist.destination {
                    ArtistDestination::Folder {
                        library_root,
                        artist_dir,
                    } => println!(
                        "  OK: work item {:?} -> place into {}",
                        artist.name,
